def MonoidHom.op {M N} [MulOneClass M] [MulOneClass N] : (M →* N) ≃ (Mᵐᵒᵖ →* Nᵐᵒᵖ) where
  toFun f  := { toFun := MulOpposite.op ∘ f ∘ unop, map_one' := congrArg MulOpposite.op f.map_one, map_mul' := fun x y => unop_injective (f.map_mul y.unop x.unop) }
  invFun f  := { toFun := unop ∘ f ∘ MulOpposite.op, map_one' := congrArg unop f.map_one, map_mul' := fun x y => congrArg unop (f.map_mul (MulOpposite.op y) (MulOpposite.op x)) }
  left_inv _ := rfl
  right_inv _  := rfl
